window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["33"]={"https://www.gov.uk/foreign-travel-advice/burkina-faso":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"c51e683012ec7337c6d94862eb6e55cb884d6ef81ab0a62715cb2e65a6212371","read":"https://www.gov.uk/api/content/foreign-travel-advice/burkina-faso","bytes":54955,"x":"fulltext v1","title":"Burkina Faso travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-03-20T00:00:00+00:00","mod":"2026-10-26T15:58:48+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"p","s":["FCDO advises against all travel to Burkina Faso."]},{"k":"p","s":["This is due to the threat of terrorist attacks and terrorist kidnap, and the unstable political situation in the country."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/burkina-faso/safety-and-security"],"."]},{"k":"h","s":["Limited consular support"]},{"k":"p","s":["There is no British Embassy in Burkina Faso and all consular support is provided from the British Embassy in Accra, Ghana. They cannot provide in-person assistance."]},{"k":"p","s":["If there is serious violence, unrest or a deterioration in the security situation, it could be difficult to leave safely. Do not rely on the British government to evacuate you as they may not be able to do so. Have your own plans on how you would leave the country, make sure you keep all travel documentation up to date and monitor the local situation."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel despite FCDO advice, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/burkina-faso/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK who choose to travel despite FCDO advice. It is based on the UK government’s understanding of Burkina Faso’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Burkina Faso set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Embassy of Burkina Faso in Brussels","https://www.ambassadeduburkinafaso.be/"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Your passport must be valid for the duration of your stay and have 2 blank pages for entry stamps."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to enter Burkina Faso."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["If you live in the UK, ",["apply for a visa online or through the Embassy of Burkina Faso in Brussels","https://www.visaburkina.bf/en/home/"],". You cannot get a visa for Burkina Faso in the UK."]},{"k":"p","s":["There are Burkinabe embassies in the West Africa region, including in Accra and Abidjan."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To pass border control in Burkina Faso, you must have a certificate to prove you’ve had a yellow fever vaccination, due to a risk of yellow fever transmission."]},{"k":"p","s":["For more details about health entry requirements and recommended vaccinations see ",["TravelHealthPro’s Burkina Faso guide","https://travelhealthpro.org.uk/country/37/burkina-faso#Vaccine_Recommendations"],"."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Burkina Faso"]},{"k":"p","s":["Terrorists are very likely to try to carry out attacks in Burkina Faso."]},{"k":"p","s":["Several terrorist groups operate in Burkina Faso, including Jama’a Nusrat ul-Islam wa al-Muslimin (JNIM) and Islamic State."]},{"k":"p","s":["There is a high threat from terrorism throughout the country, including increasingly in the capital, Ouagadougou. Terrorist attacks could be indiscriminate, including in places frequented by foreign nationals, such as:"]},{"k":"li","s":["diplomatic premises"]},{"k":"li","s":["conference centres"]},{"k":"li","s":["tourist sites"]},{"k":"li","s":["sporting and cultural events including music festivals"]},{"k":"li","s":["shopping centres"]},{"k":"li","s":["major roads and transport hubs"]},{"k":"li","s":["religious sites and places of worship, particularly churches"]},{"k":"li","s":["national parks and nature reserves"]},{"k":"li","s":["foreign, national or local government buildings"]},{"k":"li","s":["large crowds"]},{"k":"p","s":["There may be a heightened risk of attack during festivals, and religious and public holiday periods. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of the local authorities."]},{"k":"p","s":["There are frequent attacks across Burkina Faso, particularly close to the borders with Mali, Niger and Côte d’Ivoire and in the eastern region."]},{"k":"p","s":[["See also road safety","https://www.gov.uk/foreign-travel-advice/burkina-faso/safety-and-security"]]},{"k":"p","s":["Examples of significant attacks include:"]},{"k":"li","s":["in August 2024, at least 400 people were killed in a village attack in Barsalogho, Sanmatenga"]},{"k":"li","s":["in July 2024, the office of Doctors Without Borders (MSF) was attacked by gunfire in Djibo, Sahel"]},{"k":"li","s":["in February 2024, at least 15 people were killed in an attack on a church in Essakane, Oudalan"]},{"k":"li","s":["in February 2024, at least 12 people were killed in an attack on a mosque in Natiaboani, Gourma"]},{"k":"li","s":["in 2023, two foreign nationals were killed in an attack on a commercial truck convoy on the N3 (near Diori), Sahel"]},{"k":"li","s":["in 2023, around 20 people were killed in attacks on 6 villages in the southwest of Seytenga including Foufou, Mira and Lipsi"]},{"k":"hs","s":["Terrorist kidnap"]},{"k":"p","s":["There’s a very high threat of kidnapping by Al-Qaeda and regional Islamic State-affiliated groups in Burkina Faso. These include Jamaat Nusrat al-Islam wal Muslimeen (JNIM) and Islamic State Greater Sahara (ISGS ), who operate throughout Mali, Niger and Burkina Faso."]},{"k":"p","s":["A number of foreign nationals have been kidnapped and killed in Burkina Faso in recent years, especially in the northeast of the country."]},{"k":"p","s":["British nationals are seen as legitimate targets, including tourists, humanitarian aid workers, journalists and business travellers. If you are kidnapped, the reason for your presence is unlikely to protect you or secure your safe release."]},{"k":"p","s":["If you’re working or travelling in Burkina Faso, you should be aware of the risk of terrorist kidnapping. You should maintain a high level of vigilance at all times, including when travelling. You should be particularly vigilant when walking in crowded public places, including camps for displaced people, religious gatherings and insecure spaces like places of worship, markets, shopping malls, hotels, bars, night clubs, restaurants, nature reserves and national parks, and transport hubs. You should avoid regular patterns of travel and aim to only travel during daylight hours."]},{"k":"p","s":["The long-standing policy of the British government is to not make substantive concessions to hostage takers. The British government considers that paying ransoms and releasing prisoners builds the capability of terrorist groups and finances their activities. This can, in turn, increase the risk of further hostage-taking. The Terrorism Act (2000) makes payments to terrorists illegal."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["The political situation also remains unstable following the military coup on 30 September 2022. Further coups are possible. If you choose to travel to Burkina Faso, you should remain vigilant and monitor local media."]},{"k":"p","s":["The government has declared a state of emergency in the regions of:"]},{"k":"li","s":["Centre-Est"]},{"k":"li","s":["Est"]},{"k":"li","s":["Centre Nord"]},{"k":"li","s":["Nord"]},{"k":"li","s":["Boucle du Mouhoun"]},{"k":"li","s":["Sahel"]},{"k":"li","s":["Hauts-Bassins"]},{"k":"li","s":["Cascades"]},{"k":"p","s":["The measure gives security forces extra powers to conduct searches, restrict freedom of movement and detain persons of interest. Some civil rights may be suspended, including the right to protest and to hold large meetings. The military takeover in neighbouring Niger in 2023 may lead to unrest or protests in Ouagadougou."]},{"k":"p","s":["Protests are common in Burkina Faso. Avoid political rallies, gatherings and demonstrations. Crowds can gather quickly and may become violent. Foreign, national and local government facilities have been targeted and damaged in previous demonstrations."]},{"k":"p","s":["Monitor the local news to help you avoid such gatherings. If you become aware of a crowd gathering, leave the area immediately."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Vehicle crime"]},{"k":"p","s":["There is an increasing number of vehicle hold-ups on roads outside Ouagadougou. Drivers that refuse to stop when flagged down have been shot at."]},{"k":"p","s":["Armed groups have also stopped drivers to rob passengers and their vehicles. Criminals have stopped public buses to assault and rob passengers, particularly at night."]},{"k":"hs","s":["Street crime"]},{"k":"p","s":["Street crime is a serious risk for foreign visitors. Most incidents are opportunist snatches of purses, wallets, jewellery and other valuables. Thieves are particularly active near the UN Circle and the former Central Market in Ouagadougou, and are often armed. Do not carry valuables in public places or walk alone at night."]},{"k":"hs","s":["Criminal kidnapping"]},{"k":"p","s":["Kidnapping by criminal groups is widespread across Niger, Mali and Burkina Faso. There is a possibility that criminal groups could sell people they kidnap as hostages to terrorist organisations."]},{"k":"p","s":["British nationals are seen as legitimate targets, including tourists, humanitarian aid workers, journalists and business travellers. If you are kidnapped, the reason for your presence is unlikely to protect you or secure your safe release. You should avoid regular patterns of travel and aim to only travel during daylight hours."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry your passport or residence permit."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims. The dates vary by year and country. During this time, do not:"]},{"k":"li","s":["eat, drink, smoke or chew gum in public in the daytime, including in your car"]},{"k":"li","s":["play loud music or dance"]},{"k":"li","s":["swear in public"]},{"k":"p","s":["Get more advice when you arrive from your tour guide, hotel or business contacts."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["The death penalty was reinstated in Burkina Faso in October 2026 for certain offences, including:"]},{"k":"li","s":["acts of terrorism"]},{"k":"li","s":["espionage"]},{"k":"li","s":["treason"]},{"k":"li","s":["parricide"]},{"k":"li","s":["importing expired or banned products that cause death"]},{"k":"p","s":["Do not get involved in drugs of any kind. If you’re convicted of possessing or distributing any illegal drug, you can expect heavy fines and long jail sentences. Local prison conditions are harsh."]},{"k":"hs","s":["Using cameras and filmmaking"]},{"k":"p","s":["Do not take pictures of military or other government installations."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same sex sexual activity and the ‘promotion’ of same-sex relationships is a criminal offence in Burkina Faso. If convicted, such charges could lead to prison sentences of up to 5 years."]},{"k":"p","s":["There is little to no public acceptance of LGBT+ people or identities in Burkina Faso. There is an increased risk of harassment or violence against anyone thought to be part of the LGBT+ community, or perceived to be supporting their rights."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Souvenirs"]},{"k":"p","s":["There are strict customs regulations about taking cultural objects like masks, religious materials and antiquities out of Burkina Faso. If you’re unsure about buying any souvenirs you find for sale, contact the Ministry of Culture."]},{"k":"hs","s":["Money"]},{"k":"p","s":["A few of the larger hotels and restaurants in Ouagadougou accept credit cards. You’re unlikely to be able to use them anywhere outside the capital. There are a few ATMs in Ouagadougou, but they only accept Visa cards."]},{"k":"p","s":["The best option is to bring US dollars in cash to exchange."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you’re planning to drive in Burkina Faso, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["Get security advice about travelling by road in Burkina Faso."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in Burkina Faso. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["1949 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"],"."]},{"k":"hs","s":["Road safety"]},{"k":"p","s":["Roads, even if they are paved, are in a poor state of repair. Road conditions off the main roads are often difficult, especially in the rainy season from June to October. Vehicles are often in poor condition."]},{"k":"p","s":["Avoid travelling at night, even if using a local driver. Roads have very limited lighting, and vehicles often have no headlights. Livestock, pedestrians and motorbikes on the roads are additional hazards."]},{"k":"p","s":["Attacks on major roads and transport routes by terrorists are increasing, including through the use of landmines and other explosive devices. This is particularly the case in areas where terrorist groups are operational and near border areas."]},{"k":"p","s":["There is danger of armed attacks on all roads, including:"]},{"k":"li","s":["from Ouagadougou to Bobo-Dioulasso"]},{"k":"li","s":["from Bobo-Dioulasso to Côte d’Ivoire"]},{"k":"li","s":["from Fada to Benin and Togo"]},{"k":"li","s":["to Benin, Bogandée and Gayeri"]},{"k":"li","s":["to Niger"]},{"k":"p","s":["There is limited access to phone networks, so consider taking a satellite phone in case you break down or have another emergency. Always carry drinking water with you."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["The rainy season normally runs from June to October. Torrential rains can cause floods and landslides. Monitor local weather reports and expect difficulties when travelling to affected areas during this season."]},{"k":"p","s":["Find out what you can do to prepare for and respond to ",["extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 18 from Ouagadougou and ask for an ambulance."]},{"k":"p","s":["Outside Ouagadougou, call the universal emergency number 112."]},{"k":"p","s":["If you get no response, you will need to get local advice about the closest hospital and how to get to it."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Burkina Faso","https://travelhealthpro.org.uk/country/37/burkina-faso#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Burkina Faso","https://travelhealthpro.org.uk/country/37/burkina-faso"]," including:"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["Zika virus"]},{"k":"li","s":["dengue and malaria"]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Burkina Faso"]},{"k":"p","s":["Medical facilities in Burkina Faso are very limited. For serious medical treatment, evacuation to Europe is necessary. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and medical evacuation."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Burkina Faso","https://www.gov.uk/government/publications/burkina-faso-doctors-and-medical-facilities/burkina-faso-list-of-doctors-and-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Ouagadougou"]},{"k":"p","s":["Ambulance: 18"]},{"k":"p","s":["Fire: 18"]},{"k":"p","s":["Police: 17"]},{"k":"p","s":["Outside Ouagadougou, the emergency services are unlikely to respond."]},{"k":"p","s":["Take local advice instead."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Burkina%20Faso"]," and ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Burkina%20Faso"]," in Burkina Faso"]},{"k":"li","s":["dealing with a ",["death in Burkina Faso","https://www.gov.uk/government/publications/burkina-faso-bereavement-death-abroad/burkina-faso-bereavement-information"]]},{"k":"li","s":["being ",["arrested or imprisoned in Burkina Faso","https://www.gov.uk/government/publications/burkina-faso-prisoners-pack/information-pack-for-british-nationals-arrested-or-detained-in-burkina-faso"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/burkina-faso/burkina-faso"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/burkina-faso/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":16650,"change":"New information about the death penalty in Burkina Faso (‘Safety and security’ page)."},"https://www.gov.uk/foreign-travel-advice/congo":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"fc405269566c29e3ce36ca2d8aaf0b08a8e29b3219402223fbb2418389ac2674","read":"https://www.gov.uk/api/content/foreign-travel-advice/congo","bytes":45266,"x":"fulltext v1","title":"Congo travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-01-21T00:00:00+00:00","mod":"2026-10-27T12:00:20+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Republic of Congo-Central African Republic border area in Likouala Region"]},{"k":"p","s":["FCDO advises against all travel to within 50km of the Republic of Congo-Central African Republic border in Likouala Region."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/congo/regional-risks"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/congo/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Congo’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in the Republic of Congo set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the Republic of Congo Embassy in the UK."]},{"k":"p","s":["Telephone: 0203 691 5979"]},{"k":"p","s":["Email: contactambacouki@gmail.com"]},{"k":"p","s":["Address: 83 Victoria Street, London, SW1H OHW"]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Your passport must be valid for the duration of your stay. No additional period of validity is needed."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to enter the Republic of Congo."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["Apply for a visa before you travel. Contact the ",["Republic of Congo Embassy in the UK","https://www.gov.uk/government/publications/foreign-embassies-in-the-uk"]," for more information."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To pass border control in the Republic of Congo, you must have certificates to prove you’ve had:"]},{"k":"li","s":["a yellow fever vaccination, due to a risk of yellow fever transmission"]},{"k":"p","s":["For more details about health entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Republic of Congo guide","https://www.travelhealthpro.org.uk/country/55/congo#Vaccine_Recommendations"],"."]},{"k":"h","s":["Ebola"]},{"k":"p","s":["Travellers arriving in the Republic of Congo may be subject to enhanced health screening measures due to the ongoing Ebola outbreak centred in the Democratic Republic of Congo."]},{"k":"p","s":["The World Health Organisation (WHO) has ",["declared this a Public Health Emergency of International Concern","https://www.who.int/news/item/17-05-2026-epidemic-of-ebola-disease-in-the-democratic-republic-of-the-congo-and-uganda-determined-a-public-health-emergency-of-international-concern"],". ",["Check entry requirements","https://www.gov.uk/foreign-travel-advice"]," for the country you’re travelling to or transiting."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of the Republic of Congo. You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of the Republic of Congo","https://www.gov.uk/foreign-travel-advice/congo/regional-risks"],"."]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in the Republic of Congo"]},{"k":"p","s":["Although there’s no recent history of terrorism in the Republic of Congo, attacks cannot be ruled out."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["Demonstrations happen occasionally. In the past, demonstrations have become violent. Even when they are peaceful there is a risk of violence. Avoid any areas with demonstrations."]},{"k":"p","s":["The Pool Region has historically been an area of conflict between Government Forces and the Ninja insurgent group. Live conflict has not been reported since both parties signed a ceasefire agreement in 2017. Violent clashes could arise again with little or no notice in response to political events. Be vigilant for reports of local unrest."]},{"k":"h","s":["Crime"]},{"k":"p","s":["There have been reports of crime, particularly opportunistic crime such as pickpocketing, particularly in Brazzaville and Pointe Noire, and criminals may target foreigners."]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Take care of your belongings, particularly in Brazzaville and Pointe Noire. To reduce your personal risk:"]},{"k":"li","s":["avoid walking in the streets after dark"]},{"k":"li","s":["do not carry large amounts of cash or valuables"]},{"k":"li","s":["avoid isolated areas, including beaches"]},{"k":"hs","s":["Vehicle crime"]},{"k":"p","s":["Criminals may target your car. Take extra precautions against criminals targeting your vehicle, especially when travelling outside urban centres and anywhere in the Pool Region and Mouyondzi District. Reduce the risk of carjacking and break-ins by:"]},{"k":"li","s":["locking doors and keeping windows closed, including whilst travelling"]},{"k":"li","s":["not driving away from main routes"]},{"k":"li","s":["always parking in a secure location"]},{"k":"li","s":["making journeys during daylight hours in rural areas"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Police may ask you for ID. Always carry a colour copy of your passport, including your visa entry stamp. If you live in Congo, also always carry a colour copy of your residency card."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in the Republic of Congo, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can use a UK photocard driving licence to drive in the Republic of Congo. If you still have a paper driving licence, you may need to ",["update it to a photocard licence","https://www.gov.uk/exchange-paper-driving-licence"]," or get the ",["correct version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well."]},{"k":"p","s":["Hire car companies often have stricter requirements for their customers, such as a year of driving experience, a higher minimum age and holding an IDP."]},{"k":"p","s":["Some road conditions, particularly in remote parts of the country may be poor, particularly during the wet season from November to May. Reduce the risks of rural travel by using a well-maintained 4-wheel drive vehicle with necessary supplies. Travelling in convoy and in daylight will reduce the risk of being stranded if a breakdown or accident happens."]},{"k":"hs","s":["Checkpoints"]},{"k":"p","s":["There are frequent vehicle checkpoints in the Republic of Congo, which can be poorly marked. If you’re asked for documents at a checkpoint, stay in your vehicle and show them through a closed window."]},{"k":"hs","s":["Air travel"]},{"k":"p","s":["The ",["UK Air Safety List (ASL)","https://www.gov.uk/guidance/uk-air-safety-list"]," lists all known airlines in the Republic of Congo that do not meet international safety standards and are banned from operating commercial air services to, from, and within the UK. Check the UK Air Safety List when considering which airlines to fly with. The list is maintained by the Department for Transport, based on advice from the ",["UK Civil Aviation Authority","https://www.caa.co.uk/Commercial-Industry/Airlines/Licensing/Requirements-and-guidance/Third-Country-Operator-Certificates"],"."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["A passenger rail service operates between Brazzaville and Pointe Noire however, the service is often slow and unreliable."]},{"k":"hs","s":["Boat travel"]},{"k":"p","s":["The river border crossing between Brazzaville and Kinshasa can close without warning. The ferry stops running in late afternoon, does not run on Sunday and may be cancelled when there is bad weather. Check before travelling."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of the Republic of Congo. It only covers regions where FCDO has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/congo"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/congo/safety-and-security"],"."]},{"k":"h","s":["Republic of Congo-Central African Republic border area in Likouala Region"]},{"k":"p","s":["FCDO advises against all travel within 50km of the Republic of Congo-Central African Republic (CAR) border in Likouala Region."]},{"k":"p","s":["There is a risk of violence, crime and insecurity in this area due to instability in CAR."]},{"k":"h","s":["The Pool Region"]},{"k":"p","s":["Some areas in the Pool region have historically been areas of conflict between the government and the Ninja insurgent group. There have not been any reports of live conflict since a ceasefire was agreed in 2017, however a risk remains of violent clashes breaking out with little or no notice, particularly in the districts of Boko, Kindamba, Kinkala, Mayama and Mindouli."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["There’s no central number for emergency services. Check for local medical facilities and carry contact details with you."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before you travel:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for the Republic of Congo","https://www.travelhealthpro.org.uk/country/55/congo#Vaccine_Recommendations"]]},{"k":"li","s":["see how to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in the Republic of Congo","https://www.travelhealthpro.org.uk/country/55/congo#Vaccine_Recommendations"],", including:"]},{"k":"li","s":["yellow fever"]},{"k":"li","s":["schistosomiasis"]},{"k":"li","s":["malaria and dengue"]},{"k":"li","s":["mpox"]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["If you take medication, bring enough for your time in the Republic of Congo and make sure it is clearly labelled. Bring a copy of any prescription."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in the Republic of Congo"]},{"k":"p","s":["Medical facilities in the country are limited, particularly in rural areas. Medical evacuation is likely to be necessary for all but the most basic treatments. If you become ill while in the Republic of Congo or straight after leaving the country, get immediate medical advice."]},{"k":"p","s":["Make sure you have adequate travel and medical insurance to cover the cost of any medical treatment abroad and repatriation; this should specifically include the very high costs of evacuation by air ambulance."]},{"k":"p","s":["FCDO has a ",["list of medical providers in the Republic of Congo","https://www.gov.uk/government/publications/list-of-medical-facilitiespractitioners-in-the-republic-of-congo"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in the Republic of Congo"]},{"k":"p","s":["There’s no central number for emergency services in the Republic of Congo. You can report crimes to local police on 06 665 4804. Few police will speak English."]},{"k":"p","s":["Check for local medical facilities and carry contact details with you."]},{"k":"p","s":["Telephone numbers can be unreliable."]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Congo"],", ",["funeral directors","https://www.gov.uk/government/publications/list-of-funeral-directors-in-republic-of-congo/list-of-funeraldirectors-in-republic-of-congo"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=congo"]," in the Republic of Congo"]},{"k":"li","s":["dealing with a ",["death in the Republic of Congo","https://www.gov.uk/government/publications/republic-of-congo-bereavement-packinformation"]]},{"k":"li","s":["being ",["arrested or imprisoned in the Republic of Congo","https://www.gov.uk/government/publications/explanation-of-the-legal-and-prison-system-to-british-nationals"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/congo/british-embassy-kinshasa"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/congo/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]}],"chars":12378,"change":"Updated information about vaccine requirements for border control (‘Entry requirements’ page)."},"https://theconversation.com/kredibilitas-indonesia-diuji-saat-bencana-dan-asap-karhutla-melintasi-batas-negara-294803":{"r":"conversation","at":"2026-11-17T16:47Z","sha":"14e6889a6b1f370e50f6ef369b0fe2e4ee7832feb37f27428ebd884bbb29d7c5","read":"https://theconversation.com/kredibilitas-indonesia-diuji-saat-bencana-dan-asap-karhutla-melintasi-batas-negara-294803","bytes":182544,"x":"fulltext v1","title":"Kredibilitas Indonesia diuji saat bencana dan asap karhutla melintasi batas negara","by":[{"n":"Jessica Martha","r":"Dosen, Universitas Katolik Parahyangan"}],"pub":"2026-10-21T10:02:13Z","mod":"","blocks":[{"k":"p","s":["Sepanjang 2026, kebakaran hutan dan lahan (karhutla) di Indonesia kembali memicu krisis lingkungan dan kesehatan yang dampaknya ",["melampaui batas negara","https://www.bbc.com/news/articles/clyqw44w142o"],". ",["Analisis Greenpeace Indonesia","https://www.greenpeace.org/indonesia/siaran-pers/67885/warga-sesak-karena-kabut-asap-namun-pemerintah-gagal-paham-akar-masalah-karhutla-gambut"]," menemukan 5.540 titik sumber asap di 22 provinsi selama 8 Agustus hingga 20 September."]},{"k":"p","s":["Kabut asap telah menyebar ke Malaysia, Singapura, Brunei Darussalam, hingga Filipina, Thailand, Vietnam, dan Kamboja–mengganggu aktivitas warga sehari-hari."]},{"k":"p","s":[["Di Sarawak","https://news.mongabay.com/2026/09/in-southeast-asia-residents-grapple-with-life-under-indonesias-wildfire-haze/amp"],", memburuknya kualitas udara memicu lonjakan kasus asma hingga 259%. Sementara itu, tingkat polusi yang tercatat di Manila dilaporkan lebih dari empat kali lipat ambang batas aman yang ditetapkan oleh Organisasi Kesehatan Dunia (WHO)."]},{"k":"p","s":["Di Indonesia sendiri, kasus infeksi saluran pernapasan akut (ISPA) yang dikaitkan dengan karhutla di tujuh provinsi ",["mencapai 277.075 kasus","https://www.antaranews.com/berita/5785085/kemenkes-catat-277-ribu-ispa-per-oktober-kuatkan-respons-kesehatan"]," per 12 Oktober, lebih dari dua kali lipat angka pada 9 September."]},{"k":"p","s":["Read more: ",["Kasus ISPA meroket: Asap karhutla jadi ancaman senyap di daerah yang jauh dari pusat kebakaran","https://theconversation.com/kasus-ispa-meroket-asap-karhutla-jadi-ancaman-senyap-di-daerah-yang-jauh-dari-pusat-kebakaran-294660"]]},{"k":"p","s":["Kejadian ini menyoroti tantangan yang lebih besar untuk Indonesia: ketika krisis dalam negeri menjadi perhatian internasional, dampaknya tidak hanya kerusakan fisik. Krisis ini juga dapat memengaruhi hubungan diplomatik, kepercayaan publik, dan persepsi negara lain terhadap Indonesia sebagai negara yang bertanggung jawab."]},{"k":"p","s":["Oleh karena itu, cara Indonesia menanggapi dan mengomunikasikan krisis ini menjadi sangat penting, tidak hanya untuk penanganan bencana, tetapi juga untuk menjaga reputasinya pada kancah global."]},{"k":"h","s":["Ketika krisis dalam negeri menarik perhatian internasional"]},{"k":"p","s":["Dampak karhutla tidak berhenti pada kesehatan masyarakat. Karhutla juga mengganggu aktivitas ekonomi dan transportasi. Menurut ",["Reuters","https://www.reuters.com/business/environment/indonesias-burned-land-doubles-september-fires-rage-data-shows-2026-10-20/"],", lebih dari 1.400 penerbangan dibatalkan atau ditunda akibat karhutla sejak Agustus 2026."]},{"k":"p","s":["Respons negara tetangga menunjukkan bahwa persoalan ini tidak lagi terbatas pada dampak lingkungan. ",["Badan Lingkungan Hidup Nasional Singapura (NEA)","https://www.straitstimes.com/singapore/nea-issues-notices-to-three-more-companies-in-indonesia-over-haze-role"]," mengeluarkan pemberitahuan kepada sepuluh perusahaan di Indonesia. NEA meminta perusahaan-perusahaan tersebut memadamkan api, menghentikan aktivitas pembakaran, dan menyusun langkah pencegahan agar kebakaran tidak terulang."]},{"k":"p","s":["Sebelumnya, tekanan diplomatik juga muncul dari anggota parlemen Malaysia, ",["Syed Saddiq Syed Abdul Rahman","https://www.nst.com.my/news/nation/2026/10/1554575/syed-saddiq-calls-asean-pressure-indonesia-over-haze"],". Ia mengajak negara-negara ASEAN mengajukan protes diplomatik kepada Indonesia karena dinilai belum berbuat cukup untuk mengendalikan karhutla."]},{"k":"p","s":["Rangkaian peristiwa ini menunjukkan bahwa karhutla dapat memengaruhi hubungan Indonesia dengan negara lainnya. Bagi Indonesia yang ingin berperan lebih besar di tingkat regional dan global, krisis ini menjadi ujian kredibilitas dalam mengangani risiko lingkungan lintas batas."]},{"k":"p","s":["Kredibilitas tidak hanya ditentukan oleh penanganan di lapangan, tetapi juga oleh cara pemerintah menyampaikan informasi, merespons kekhawatiran, dan menjelaskan upaya yang sedang dilakukan. Komunikasi menjadi penting karena ikut membentuk persepsi dan kepercayaan publik internasional terhadap Indonesia."]},{"k":"p","s":["Lalu, ketika karhutla melintasi batas negara, bagaimana komunikasi pemerintah Indonesia dapat melindungi masyarakat terdampak sekaligus menjaga kepercayaan internasional?"]},{"k":"h","s":["Komunikasi krisis sebagai diplomasi publik"]},{"k":"p","s":[["Ingrid d’Hooghe","https://doi.org/10.1163/9789004283954_009"],", peneliti senior dan mantan Kepala Clingendael China Centre, menjelaskan bahwa ketika krisis dalam negeri menjadi perhatian internasional, pemerintah perlu berkomunikasi dengan masyarakat di dalam maupun luar negeri melalui tiga jenis informasi: informasi untuk menghadapi dampak fisik, informasi untuk menghadapi dampak psikologis, dan komunikasi untuk memulihkan reputasi."]},{"k":"p","s":["Informasi untuk menghadapi dampak fisik berupa panduan untuk mengurangi risiko. Dalam konteks karhutla, informasi ini mencakup pembaruan kualitas udara, wilayah terdampak, risiko kesehatan, dan langkah-langkah perlindungan yang dapat dilakukan masyarakat."]},{"k":"p","s":["Ketika ",["kualitas udara Pontianak memasuki kategori berbahaya","https://www.cnnindonesia.com/teknologi/20260901090426-641-1398601/kualitas-udara-pontianak-masuk-kategori-berbahaya-paling-buruk-di-ri"],", masyarakat membutuhkan informasi jelas mengenai risiko paparan asap dan cara mengurangi dampaknya terhadap kesehatan."]},{"k":"p","s":["Menurut ",["WHO","https://www.who.int/news-room/questions-and-answers/item/air-pollution-personal-interventions-and-risk-communication?utm_source=chatgpt.com"],", tersedianya informasi kualitas udara dan imbauan kesehatan yang mudah dipahami dapat membantu masyarakat mengambil langkah untuk mengurangi dampak polusi dan melindungi kesehatan, terutama kelompok rentan seperti anak-anak, lansia, dan orang dengan penyakit pernapasan."]},{"k":"p","s":["Informasi untuk menghadapi dampak psikologis berfungsi untuk mengurangi kecemasan dan ketidakpastian. Dalam situasi karhutla yang berkepanjangan, masyarakat memerlukan pembaruan informasi yang konsisten mengenai upaya pemadaman, perkembangan kondisi asap, dan langkah pemerintah untuk melindungi warga. Komunikasi juga perlu menunjukkan kepedulian terhadap kondisi masyarakat yang terdampak, bukan sekadar menyampaikan informasi teknis."]},{"k":"p","s":["Dampak komunikasi krisis juga melampaui batas negara. Informasi yang konsisten dan disampaikan tepat waktu memungkinkan pemerintah negara tetangga menilai risiko dan mengoordinasikan respons mereka masing-masing. Sebaliknya, sikap diam, informasi yang simpang siur, atau keterlambatan komunikasi dapat menyulitkan dan memengaruhi kepercayaan negara lain terhadap penanganan krisis oleh Indonesia."]},{"k":"h","s":["Krisis yang berbeda, tantangan diplomatik yang berbeda"]},{"k":"p","s":["Jenis informasi ketiga, yakni komunikasi untuk memulihkan reputasi, menghadirkan tantangan tersendiri karena tidak semua bencana membawa dampak yang sama terhadap reputasi negara."]},{"k":"p","s":[["Pemulihan reputasi","https://doi.org/10.1163/9789004283954_009"]," merujuk pada strategi penyampaian informasi dan komunikasi untuk memperbaiki citra negara yang telanjur rusak. Hal ini semakin relevan ketika krisis berkaitan dengan tindakan yang dapat dipertanggungjawabkan kepada pihak tertentu, kurangnya upaya pencegahan, atau penanganan yang tidak memadai sehingga negara dianggap bertanggung jawab dan dikritik."]},{"k":"p","s":["Kebakaran hutan menghadirkan tantangan berbeda karena ",["sebagian besar kebakaran disebabkan","https://theconversation.com/borneo-forest-fires-spike-again-why-el-nino-isnt-the-sole-culprit-290334"]," oleh aktivitas manusia, kelalaian, dan lemahnya penegakan hukum."]},{"k":"p","s":["Read more: ",["Mengapa sanksi pelaku karhutla amat timpang dengan kerugian berantai yang ditimbulkannya?","https://theconversation.com/mengapa-sanksi-pelaku-karhutla-amat-timpang-dengan-kerugian-berantai-yang-ditimbulkannya-290256"]]},{"k":"p","s":["Dalam kasus seperti ini, sekadar mengaitkan kebakaran dengan cuaca kering atau ",["fenomena Super El Niño","https://news.detik.com/berita/d-8628464/bmkg-ungkap-penyebab-karhutla-di-kalimantan-iklim-kering-efek-el-nino"]," dapat menimbulkan reaksi negatif di luar negeri. Bagi masyarakat di Kuching atau Manila yang menghirup asap, penjelasan menggunakan kondisi iklim bisa terdengar seperti alasan untuk menghindari tanggung jawab."]},{"k":"p","s":["Kata-kata saja ",["tidak cukup untuk memulihkan reputasi","https://doi.org/10.1016/S0363-8111(97)90023-0"]," ketika masyarakat menuntut tindakan nyata. Pemerintah perlu menegakkan hukum lingkungan, mengusut pihak yang bertanggung jawab, memperkuat pencegahan kebakaran, dan mengatasi kondisi yang memungkinkan kebakaran terus berulang."]},{"k":"p","s":["Perbedaan ini sangat krusial dalam hubungan diplomatik. Bencana alam menguji kemampuan Indonesia menanggapi ancaman yang tidak dapat dihindari, sedangkan krisis kebakaran yang terus berulang juga menguji kesediaan Indonesia dan negara-negara tetangganya untuk berkomunikasi secara terbuka mengenai tanggung jawab bersama atas risiko yang melintasi perbatasan."]},{"k":"h","s":["Apa yang perlu disampaikan dan dilakukan Indonesia?"]},{"k":"p","s":["Bagi Indonesia, komunikasi bencana bukan sekadar upaya menyampaikan informasi kepada masyarakat. Komunikasi juga merupakan bagian dari diplomasi publik."]},{"k":"p","s":["Pemerintah perlu menyampaikan informasi secara tepat, terbuka, dan konsisten. Namun, komunikasi harus berjalan seiring dengan tindakan nyata: melindungi masyarakat, menunjukkan akuntabilitas, dan keseriusan dalam melakukan pencegahan."]},{"k":"p","s":["Pada akhirnya, reputasi Indonesia di mata dunia selama krisis tidak hanya ditentukan oleh apa yang disampaikan pemerintah, tetapi juga oleh keselarasan antara pernyataan dan tindakan yang benar-benar dilakukan."]}],"chars":7577},"https://theconversation.com/fasilitas-ada-tapi-sulit-diakses-mengapa-pelayanan-publik-ramah-difabel-masih-langka-di-indonesia-293693":{"r":"conversation","at":"2026-11-17T16:47Z","sha":"61d2fe602c2c6d701b3afbc145d05aff569221362c33bfed280fd1d58e98fb26","read":"https://theconversation.com/fasilitas-ada-tapi-sulit-diakses-mengapa-pelayanan-publik-ramah-difabel-masih-langka-di-indonesia-293693","bytes":179672,"x":"fulltext v1","title":"Fasilitas ada, tapi sulit diakses: Mengapa pelayanan publik ramah difabel masih langka di Indonesia","by":[{"n":"Muhammad Dzulfikar Al Ghofiqi","r":"Dosen dan Peneliti di Departemen Administrasi Publik, Fakultas Ilmu Sosial dan Ilmu Politik, Universitas Airlangga, Universitas Airlangga"}],"pub":"2026-10-21T01:36:27Z","mod":"","blocks":[{"k":"p","s":["● Aturan dan fasilitas belum menjamin layanan publik yang aksesibel bagi difabel."]},{"k":"p","s":["● Pelibatan komunitas difabel membantu pemerintah menemukan dan memperbaiki hambatan layanan."]},{"k":"p","s":["● Partisipasi harus dilembagakan agar perbaikan layanan tidak bergantung pada individu."]},{"k":"p","s":["Sudah sedekade ",["Undang-Undang Nomor 8 Tahun 2016","https://peraturan.bpk.go.id/Details/37251/uu-no-8-tahun-2016"]," tentang Penyandang Disabilitas disahkan, tapi kondisi orang difabel tak banyak berubah."]},{"k":"p","s":["Ragam persoalan warisan dahulu kala seperti jalur pemandu yang terputus, informasi yang tidak tersedia dalam format aksesibel, dan petugas yang kesulitan berkomunikasi dengan pengguna difabel masih jadi makanan sehari-hari."]},{"k":"p","s":["Masalahnya bukan semata-mata kekurangan fasilitas. Pemerintah juga perlu memastikan orang disabilitas dilibatkan sejak layanan dirancang, bukan baru didengarkan setelah masalah muncul. Tanpa keterlibatan pengguna, kebijakan yang terlihat memadai di atas kertas bisa gagal menjawab kebutuhan warga."]},{"k":"p","s":["Melansir ",["Ombudsman RI","https://ombudsman.go.id/news/r/wujudkan-pelayanan-publik-inklusif-ombudsman-ri-dan-knd-perkuat-sinergi-pengawasan?utm_source=chatgpt.com"],", laporan terkait disabilitas meningkat setiap tahun. Sementara itu, ",["Komisi Nasional Disabilitas","https://ombudsman.go.id/pers/r/wujudkan-pelayanan-publik-inklusif-ombudsman-ri-dan-knd-perkuat-sinergi-pengawasan"]," menilai pemenuhan hak penyandang disabilitas dalam pelayanan publik masih belum optimal."]},{"k":"p","s":["Pengalaman Mal Pelayanan Publik (MPP) Kabupaten Lamongan, Jawa Timur, menunjukkan bagaimana keterlibatan komunitas difabel dapat membantu memperbaiki layanan."]},{"k":"p","s":[["Riset kami","https://doi.org/10.1002/pad.70074"],", yang melibatkan 27 informan dan diterbitkan dalam jurnal Public Administration and Development pada 2026, menemukan bahwa perbaikan membutuhkan kapasitas pemerintah sekaligus komunitas yang mampu menyampaikan kritik dan mengawal tindak lanjutnya."]},{"k":"p","s":["Read more: ",["4 tantangan pelayanan publik berbasis digital di Indonesia","https://theconversation.com/4-tantangan-pelayanan-publik-berbasis-digital-di-indonesia-203848"]]},{"k":"h","s":["Standar pemerintah tak sesuai kebutuhan warga"]},{"k":"p","s":["Saat MPP Lamongan mulai beroperasi, pemerintah telah memiliki standar operasional prosedur (SOP) layanan prioritas. Namun, komunitas difabel tidak dilibatkan sejak awal penyusunannya. Akibatnya, rancangan layanan belum sepenuhnya menjawab kebutuhan pengguna."]},{"k":"p","s":["Tak ada jalur pemandu dan informasi Braille untuk tuna netra. Teman tuli kesulitan berkomunikasi karena sedikit petugas yang memahami bahasa isyarat. Sementara itu, disabilitas fisik dipaksa melewati bidang miring yang curam dan mendatangi loket di lantai dua."]},{"k":"p","s":["Kondisi tersebut memperlihatkan kelemahan birokrasi yang terlalu mengandalkan kepatuhan administratif alias cuma sekadar memenuhi kewajiban. Keberadaan SOP dan fasilitas tidak otomatis membuktikan bahwa layanan dapat digunakan semua orang."]},{"k":"p","s":["Bagi warga yang datang untuk mengurus dokumen, mengakses layanan tanpa bantuan dan panduan yang sesuai justru membuat antrean makin mengular. Pemerintah seharusnya mengukur keberhasilan layanan dari pengalaman pengguna, bukan hanya dari fasilitas yang tersedia atau prosedur yang telah ditetapkan."]},{"k":"p","s":["Temuan ini sejalan dengan ",["tinjauan sistematis","https://onlinelibrary.wiley.com/doi/10.1111/padm.13049?__cf_chl_rt_tk=RFT7PekkjGmTbt0fKdx51myyKANimenE6O_SxEbHxL8-1791981261-1.0.1.1-SWlKLwpmyqvzv7z45GyHJ9B_NKBLZp7s7bbZ0tJm6Yc"]," yang mengkaji 119 penelitian tentang inklusi warga dalam layanan publik. Kajian tersebut menyoroti pentingnya memahami bagaimana interaksi warga dengan layanan membentuk pengalaman inklusi, sekaligus bagaimana hambatan administratif dapat menghalanginya."]},{"k":"p","s":["Read more: ",["Mengapa layanan kesehatan untuk disabilitas di Indonesia masih belum maksimal?","https://theconversation.com/mengapa-layanan-kesehatan-untuk-disabilitas-di-indonesia-masih-belum-maksimal-247473"]]},{"k":"h","s":["Ubah keluhan menjadi perubahan"]},{"k":"p","s":["Di Lamongan, komunitas difabel berupaya mengubah pengalaman individual menjadi tuntutan bersama."]},{"k":"p","s":["Pada Desember 2020, melalui ",["Festival Inklusi","https://timesindonesia.co.id/peristiwa-daerah/314234/penyandang-disabilitas-inginkan-guiding-block-di-semua-trotoar-kota-lamongan"],", mereka menyuarakan kebutuhan agar jalur pemandu tunanetra diperluas ke seluruh trotoar kota. Jalur yang tersedia di alun-alun belum menjamin perjalanan yang aman ketika akses terputus di lokasi lain."]},{"k":"p","s":["Berbagai organisasi kemudian menghimpun aspirasi melalui Forum Perlindungan dan Pemenuhan Hak Penyandang Disabilitas (FP2HD). Forum ini membantu komunitas menyusun usulan, berkomunikasi dengan pemerintah, dan mengawal respons atas hambatan yang mereka alami."]},{"k":"p","s":["Melalui forum konsultasi publik, masukan komunitas turut mendorong perubahan alur pelayanan yang dimulai dari area parkir, penyediaan ruang layanan khusus di lantai satu, penempatan petugas yang dibekali keterampilan bahasa isyarat, serta pengembangan kompetensi pegawai dan dukungan anggaran."]},{"k":"p","s":[["Penelitian tentang aksesibilitas layanan puskesmas di Bandung","https://knia.stialanbandung.ac.id/index.php/knia/article/view/595"]," juga menunjukkan pentingnya pelibatan masyarakat dalam perbaikan fasilitas publik. Namun, tentunya partisipasi ini tidak boleh menjadi cara pemerintah memindahkan tanggung jawab kepada warga."]},{"k":"p","s":["Read more: ",["6 penghalang keterlibatan penyandang disabilitas dalam proses pembangunan","https://theconversation.com/6-penghalang-keterlibatan-penyandang-disabilitas-dalam-proses-pembangunan-108176"]]},{"k":"h","s":["Partisipasi harus jadi kewajiban kelembagaan"]},{"k":"p","s":["Pengalaman Lamongan menunjukkan bahwa kritik komunitas dapat membantu pemerintah mengenali kekurangan yang luput dari perencanaan. Namun, perbaikan akan rapuh jika bergantung pada pejabat tertentu atau kegigihan segelintir aktivis."]},{"k":"p","s":["Karena itu, pemerintah perlu melembagakan partisipasi melalui tiga langkah."]},{"k":"p","s":["Pertama, libatkan organisasi difabel sejak penyusunan dan evaluasi SOP, pembangunan fasilitas, hingga penentuan anggaran. Pengujian layanan harus melibatkan pengguna dengan ragam disabilitas karena kebutuhan mereka berbeda-beda."]},{"k":"p","s":["Kedua, setiap masukan harus memiliki penanggung jawab, tenggat waktu, dan tindak lanjut yang dapat diperiksa publik. Pemerintah juga perlu menjelaskan alasan jika usulan belum dapat dilaksanakan."]},{"k":"p","s":["Ketiga, sediakan forum konsultasi yang aksesibel dan dukungan bagi komunitas untuk memantau layanan secara independen. Kritik tidak boleh bergantung pada kedekatan komunitas dengan pejabat yang sedang menjabat."]},{"k":"p","s":["Riset satu kasus tidak dapat mewakili seluruh Indonesia. Namun, pelajarannya relevan: pemerintah tidak cukup mengklaim layanan telah inklusif hanya karena aturan dan fasilitas tersedia."]},{"k":"p","s":["Ukuran keberhasilannya adalah apakah orang difabel dapat memperoleh informasi, berkomunikasi dengan petugas, mengakses fasilitas, dan menyelesaikan urusan secara aman dan bermartabat."]},{"k":"p","s":["Layanan publik baru benar-benar inklusif ketika penyandang disabilitas bukan sekadar penerima layanan, melainkan turut menentukan bagaimana layanan dirancang, dijalankan, dan dievaluasi."]},{"k":"p","s":["Read more: ",["Mendorong penelitian inklusif: Penyandang disabilitas perlu terlibat aktif, bukan hanya sebagai objek","https://theconversation.com/mendorong-penelitian-inklusif-penyandang-disabilitas-perlu-terlibat-aktif-bukan-hanya-sebagai-objek-242911"]]}],"chars":6003},"https://theconversation.com/wab-kinew-wants-the-indian-act-gone-its-an-opportunity-to-trade-old-colonial-rules-for-new-nation-to-nation-relations-295434":{"r":"conversation","at":"2026-11-17T16:47Z","sha":"3ad6a91538194c83dc1fc1a839cd545ea61f45cd3d693ca92fc463b064e6ef71","read":"https://theconversation.com/wab-kinew-wants-the-indian-act-gone-its-an-opportunity-to-trade-old-colonial-rules-for-new-nation-to-nation-relations-295434","bytes":189621,"x":"fulltext v1","title":"Wab Kinew wants the Indian Act gone: It’s an opportunity to trade old colonial rules for new nation-to-nation relations","by":[{"n":"Frank Deer","r":"Professor, Faculty of Education, University of Manitoba"}],"pub":"2026-11-02T16:31:27Z","mod":"","blocks":[{"k":"p","s":["Manitoba Premier Wab Kinew recently ",["called for the abolition of the Indian Act","https://www.cjme.com/2026/10/26/kinew-calls-on-carney-to-abolish-the-indian-act-at-meeting-with-chiefs/"]," during a meeting in Ottawa with Prime Minister Mark Carney, provincial premiers and First Nations leaders."]},{"k":"p","s":["Holding up his ",["Indian status card","https://www.sac-isc.gc.ca/eng/1100100032374/1572457769548"],", Kinew questioned why Canada continues to maintain legislation that classifies Indigenous people according to a federally administered system of identity."]},{"k":"p","s":["Some have called his remarks a ",["distraction from the conversation on resource extraction","https://music.youtube.com/watch?v=jwE6pb9KLlI"],". A few Conservatives have called it ",["an empty academic exercise","https://www.winnipegfreepress.com/canada/2026/10/27/carney-says-ottawas-indian-act-review-might-not-end-up-abolishing-the-law"],". And still others have called it bold."]},{"k":"p","s":["But no matter what you think of his motivations, Kinew’s call ",["raises important questions about the relationship between First Nations and the Canadian state","https://truenorthaid.ca/indigenous-self-determination/"],", particularly concerning Indigenous nationhood and self-determination."]},{"k":"h","s":["What is the Indian Act?"]},{"k":"p","s":["First ",["enacted in 1876","https://yellowheadinstitute.org/2026/the-indian-act-exit-150/"],", the Indian Act consolidated earlier colonial legislation intended to regulate the lives of First Nations Peoples. The legislation established federal authority over reserve lands, political governance and the legal recognition of Indigenous identity."]},{"k":"p","s":["The ",["Canadian government acknowledges","https://cirnac.gc.ca/eng/1307460755710/1536862806124"]," the legislation was founded on the assumption that First Nations required federal guardianship until they could be integrated into Canadian society."]},{"k":"p","s":["The consequences of this approach have been profound. The ",["Indian Act","https://thecanadianencyclopedia.ca/en/article/indian-act"]," and associated federal policies undermine traditional systems of governance. Historically, it has restricted cultural and ceremonial practices."]},{"k":"p","s":["It ",["contributed to the assimilationist policies that supported the residential school system","https://www.facinghistory.org/en-ca/resource-library/historical-background-indian-act-indian-residential-schools"],". The legislation also established discriminatory provisions that historically ",["deprived some First Nations women and their descendants of Indian status","https://thecanadianencyclopedia.ca/en/article/bill-c-31"],"."]},{"k":"p","s":["Despite numerous amendments, ",["the Indian Act continues to influence how numerous First Nations are governed. It still determines how their members are recognized under Canadian law","https://www.cbc.ca/radio/unreserved/how-the-indian-act-continues-to-impact-the-lives-of-first-nation-people-1.5614187"],"."]},{"k":"h","s":["First Nations Peoples remain skeptical"]},{"k":"p","s":["Kinew’s remarks invite consideration of a fundamental contradiction. While ",["Canada professes a commitment to nation-to-nation relations","https://www.justice.gc.ca/eng/csj-sjc/principles-principes.html"],", much of its relationships with First Nations continues to operate through legislation premised upon federal authority over them."]},{"k":"p","s":["Kinew’s call suggests First Nations should work with the Canadian government on the abolishment of the Indian Act and toward a replacement."]},{"k":"p","s":["There are good reasons for First Nations Peoples to remain skeptical of the federal government’s commitment to working with them. Canada’s history is marked by repeated failures by governments to honour First Nations rights, treaties and political authority."]},{"k":"p","s":["For example, the ",["1990 Oka Crisis","https://cirnac.gc.ca/eng/1307460755710/1536862806124#chp6"]," was an episode in which Mohawk people defended ancestral lands against proposed development; the confrontation led to my First Nation existing under military occupation."]},{"k":"p","s":["More recently, the proposed ",["Bill C-39","https://afn.ca/legislation-to-watch/bill-c-39/"],", intended to accelerate major project approvals, raises concerns about whether expedited decision-making on development affecting traditional lands and rights sidesteps First Nations consultation."]},{"k":"p","s":["Such concerns raise questions about Canada’s willingness to recognize First Nations nationhood. Against this historical backdrop, promises of reconciliation and nation-to-nation relations warrant careful scrutiny."]},{"k":"h","s":["First Nations: Distinct political communities"]},{"k":"p","s":["A genuine nation-to-nation relationship requires more than recognition of Indigenous rights within Canada. It requires recognition that First Nations are distinct political communities possessing their own histories, laws, governing traditions and understandings of nationhood."]},{"k":"p","s":["A nation-to-nation relationship should be grounded in mutual respect and the right of nations to determine their own political futures, a principle affirmed by the ",["United Nations Declaration on the Rights of Indigenous Peoples","https://www.justice.gc.ca/eng/declaration/decl_doc.html"],"."]},{"k":"p","s":["The ",["Indian Act","https://laws-lois.justice.gc.ca/eng/acts/I-5/"]," has never been particularly well-suited for this purpose. Established as an instrument of colonial administration, it presumes that significant aspects of First Nations political life should be governed through legislation created and maintained by the federal government. This arrangement is difficult to reconcile with the principle that First Nations possess an inherent right to govern themselves."]},{"k":"p","s":[["Kinew’s call to abolish the act","https://www.aptnnews.ca/national-news/manitoba-premier-wab-kinew-calls-on-prime-minister-to-abolish-the-indian-act-at-meeting-with-chiefs/"]," may present an important opportunity, one in which questions about what legislation might replace the Indian Act should be discussed."]},{"k":"p","s":["But more fundamentally, it should encourage First Nations Peoples to consider the realities of the Indian Act and how they understand their own nationhood and the political relationships they want to establish with Canada."]},{"k":"h","s":["Emancipation isn’t charity"]},{"k":"p","s":["This is where the idea of native auto-emancipation becomes particularly relevant. In 1882, Jewish writer ",["Leo Pinsker argued in his 1882 pamphlet Auto-Emancipation","https://www.posenlibrary.com/entry/autoemancipation-birth-jewish-nationalism"]," that Jewish emancipation could not depend exclusively upon the goodwill or recognition of other nations. Jewish people needed to take responsibility for their own collective political future."]},{"k":"p","s":["Although the historical circumstances of Jewish and Indigenous Peoples differ considerably, Pinsker’s argument offers a useful point of reflection."]},{"k":"p","s":["For generations, First Nations Peoples have been encouraged, and sometimes compelled, to understand their place within Canadian political and social institutions. This integrationist approach risks making Indigenous nationhood dependent upon the extent to which it is accommodated or recognized by Canada rather than upon the ",["inherent right of Indigenous Peoples to self-determination","https://www.justice.gc.ca/eng/declaration/themes.html"],"."]},{"k":"p","s":["Native auto-emancipation suggests a different starting point. Rather than asking how First Nations might find greater recognition within Canada and its institutions, Indigenous Peoples should continue to ask what it means to belong to their own nations."]},{"k":"p","s":["This is not a new question. For instance, in the 2009 ",["Peace, Power, and Righteousness: an Indigenous Manifesto,","https://global.oup.com/academic/product/peace-power-righteousness-9780195430516"],", Kahnawà:ke author Taiaiake Alfred explores the importance of Indigenous Peoples returning to their traditional political and governmental ways."]},{"k":"p","s":["To engage with such change would be to increase attention on such things as Indigenous languages, laws, histories, territories and responsibilities. The ",["United Nations Declaration on the Rights of Indigenous Peoples","https://laws.justice.gc.ca/eng/acts/U-2.2/FullText.html"],", particularly Article 33, affirms the right of Indigenous Peoples to determine their own identity, membership and political institutions."]},{"k":"h","s":["Avoiding a reliance on Canada"]},{"k":"p","s":["Abolishing the Indian Act might create opportunities for meaningful change, provided that ",["existing rights and protections are preserved","https://www.btpm.org/ontario-news/2026-10-28/canadian-indigenous-leaders-meet-to-discuss-reforming-abolishing-divisive-indian-act"],"."]},{"k":"p","s":["But the more fundamental transformation may involve First Nations Peoples continuing to orient their identities, responsibilities and political leanings toward their own nationhood, and to avoid relying on Canada to define the terms of their political existence."]},{"k":"p","s":["Some may believe Kinew’s call to abolish the Indian Act was bold. Some believe that ",["his message was presumptuous and that he may have been attempting to speak for other First Nations people","https://www.ctvnews.ca/politics/article/pm-carney-says-its-time-to-move-beyond-indian-act/"],". But any card-carrying Status Indian is entitled to opine on the continued existence of the Indian Act."]},{"k":"p","s":["One way of addressing the Manitoba premier’s words is to allow them to fuel a conversation. If First Nations are interested in establishing a real nation-to-nation relationship with Canada, one where their nationhood, sovereignty and inherent right to self-determination are acknowledged and respected, then the extent to which the Indian Act enables such a relationship should be carefully considered."]}],"chars":7501}};
